/// Defines safe wrappers for nifly classes that sit below `NiAVObject`.
///
/// For each `Name(FfiType): Parent => upcast_fn, downcast_fn;` this generates:
/// - `#[repr(transparent)] pub struct Name(ffi::FfiType)` with a crate-private `from_ffi`
/// - `Deref<Target = Parent>` through `ffi::upcast_fn`, and `DerefMut` to the same object
/// - `NiType`, so `NiObject::downcast::<Name>()` works, through `ffi::downcast_fn`
/// - the doc section `docs/handle_methods/Name.md`, generated by `tests/it/handle_methods.rs`
///
/// `ffi` is the bridge module the types and shims live in.
macro_rules! ni_types {
    ($ffi_mod:ident; $(
        $(#[$meta:meta])*
        $name:ident($ffi:ident): $parent:ty => $upcast:ident, $downcast:ident;
    )*) => {$(
        $(#[$meta])*
        #[doc = include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"), "/docs/handle_methods/", stringify!($name), ".md"
        ))]
        #[derive(::ref_cast::RefCastCustom)]
        #[repr(transparent)]
        pub struct $name($ffi_mod::$ffi);

        impl $name {
            #[::ref_cast::ref_cast_custom]
            #[allow(dead_code)]
            pub(crate) fn from_ffi(inner: &$ffi_mod::$ffi) -> &Self;

            /// The pinned C++ object, for calling mutating shims.
            #[allow(dead_code)]
            pub(crate) fn ffi_mut(&mut self) -> ::std::pin::Pin<&mut $ffi_mod::$ffi> {
                // SAFETY: the C++ object never moves: the wrapper is zero-sized, so moving
                // or swapping it through `&mut self` copies nothing.
                unsafe { ::std::pin::Pin::new_unchecked(&mut self.0) }
            }
        }

        const _: () = $crate::objects::assert_zero_sized::<$name>();

        impl ::std::ops::Deref for $name {
            type Target = $parent;

            fn deref(&self) -> &$parent {
                <$parent>::from_ffi($ffi_mod::$upcast(&self.0))
            }
        }

        impl ::std::ops::DerefMut for $name {
            fn deref_mut(&mut self) -> &mut $parent {
                $crate::objects::upcast_mut(self)
            }
        }

        impl $crate::objects::Sealed for $name {}

        impl $crate::objects::HasParent for $name {
            type Parent = $parent;
        }

        impl $crate::objects::NiType for $name {
            fn downcast_from(obj: &$crate::objects::NiObject) -> Option<&Self> {
                // SAFETY: the shim returns either null or a pointer to the same
                // object as `obj`, so it has the same lifetime.
                unsafe { $ffi_mod::$downcast(obj.as_ffi()).as_ref() }.map(Self::from_ffi)
            }

            fn as_object(&self) -> &$crate::objects::NiObject {
                <$parent as $crate::objects::NiType>::as_object(::std::ops::Deref::deref(self))
            }
        }
    )*};
}

/// Getter and setter pairs over the bridge's field shims, converting with `$to` and `$from`.
macro_rules! fields {
    ($($(#[$doc:meta])* $get:ident, $set:ident: $ty:ty = $ffi_get:ident, $ffi_set:ident, $to:expr, $from:expr;)*) => {$(
        $(#[$doc])*
        pub fn $get(&self) -> $ty {
            ($to)(ffi::$ffi_get(&self.0))
        }

        #[doc = concat!("Sets [`", stringify!($get), "`](Self::", stringify!($get), ").")]
        pub fn $set(&mut self, value: $ty) {
            ffi::$ffi_set(self.ffi_mut(), ($from)(value));
        }
    )*};
}

/// A typed getter and setter over a `u32` field shim; values outside `$ty` read as `None`.
macro_rules! enum_field {
    ($(#[$doc:meta])* $get:ident, $set:ident: $ty:ty = $ffi_get:ident, $ffi_set:ident) => {
        $(#[$doc])*
        pub fn $get(&self) -> Option<$ty> {
            <$ty>::try_from(ffi::$ffi_get(&self.0)).ok()
        }

        #[doc = concat!("Sets [`", stringify!($get), "`](Self::", stringify!($get), ").")]
        pub fn $set(&mut self, value: $ty) {
            ffi::$ffi_set(self.ffi_mut(), value.into());
        }
    };
}

/// Implements the marker trait `$tr` for each type. The one form for marker trait impls, which
/// `tests/it/handle_methods.rs` parses.
macro_rules! impl_marker {
    ($tr:ident: $($t:ident)*) => {$(impl $tr for $t {})*};
}
